using DriveOS.Modules.Workforce.Domain.EquipmentAssignments; using DriveOS.SharedKernel.Identifiers; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.Workforce.Infrastructure.Persistence.Configurations;
internal sealed class EquipmentAssignmentConfiguration:IEntityTypeConfiguration<EquipmentAssignment>{public void Configure(EntityTypeBuilder<EquipmentAssignment> b){b.ToTable("equipment_assignments");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new EquipmentAssignmentId(x)).ValueGeneratedNever();b.Property(x=>x.OrganizationId).HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.EmployeeId).HasConversion(x=>x.Value,x=>new EmployeeId(x));b.Property(x=>x.ResourceType).HasConversion<int>();b.Property(x=>x.Status).HasConversion<int>();b.Property(x=>x.HandoverCondition).HasConversion<int>();b.Property(x=>x.ReturnCondition).HasConversion<int>();b.Property(x=>x.HandoverNotes).HasMaxLength(1000);b.Property(x=>x.ReturnNotes).HasMaxLength(1000);b.Property(x=>x.CancellationReason).HasMaxLength(512);b.Property(x=>x.HandedOverByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.ReturnedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.CreatedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.LastModifiedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.HasIndex(x=>new{x.OrganizationId,x.EmployeeId,x.Status});b.HasIndex(x=>new{x.OrganizationId,x.ResourceType,x.ResourceId,x.Status});b.HasIndex(x=>new{x.OrganizationId,x.StartDate,x.PlannedEndDate});}}
